update public.learning_paths
set
  title = 'Social Work Ethics',
  goal = 'Social Work Ethics',
  summary = 'Social Work Ethics prepares students to identify, analyze, document, and respond to ethical issues in professional social work practice. Students study the NASW Code of Ethics, ethical principles, decision-making models, confidentiality, informed consent, boundaries, dual relationships, self-disclosure, professional competence, documentation, risk management, digital practice, research ethics, policy advocacy, and justice-centered practice. The course is case-driven and practice-centered. Students repeatedly apply standards to realistic dilemmas, consult across roles, write defensible documentation, examine power and oppression, and build a reflective professional identity capable of handling ambiguity without abandoning social work values.',
  data = $swetjson${"slug": "social-work-ethics", "title": "Social Work Ethics", "description": "Social Work Ethics prepares students to identify, analyze, document, and respond to ethical issues in professional social work practice. Students study the NASW Code of Ethics, ethical principles, decision-making models, confidentiality, informed consent, boundaries, dual relationships, self-disclosure, professional competence, documentation, risk management, digital practice, research ethics, policy advocacy, and justice-centered practice. The course is case-driven and practice-centered. Students repeatedly apply standards to realistic dilemmas, consult across roles, write defensible documentation, examine power and oppression, and build a reflective professional identity capable of handling ambiguity without abandoning social work values.", "topics": [{"id": "2355dfb5-f17b-425c-b6ca-991b5d098ad7", "type": "topic", "title": "Foundations of Social Work Ethics and Professional Values", "description": "Students begin by understanding ethics as the practical discipline that connects social work values to real decisions, relationships, institutions, and consequences.", "children": [{"id": "298661e6-d6f6-4d5c-bc4a-7f71cce30022", "type": "subtopic", "title": "Values, ethics, and professional identity", "children": [{"id": "8839b3d4-374a-4386-b941-a5f482d7d0f1", "type": "concept", "title": "Service, social justice, dignity, relationships, integrity, and competence"}, {"id": "2cf3ae1f-c061-4770-b565-2258426dba42", "type": "concept", "title": "Values, principles, standards, laws, policies, and personal morality"}, {"id": "53799fa6-8804-4066-b617-75bf611d83c2", "type": "concept", "title": "Professional identity, public trust, and responsibility to clients and communities"}], "description": "Students learn why social work ethics is more than rule-following: it is the disciplined translation of values into action."}, {"id": "8900dfe6-9a92-4583-8379-4ae165bebfa8", "type": "subtopic", "title": "Ethical tensions in social work", "children": [{"id": "ef283346-ddad-4c15-900f-8c59bc7c09c4", "type": "concept", "title": "Self-determination versus protection"}, {"id": "4c57dbcf-dd23-467c-a593-ca4ab944d980", "type": "concept", "title": "Confidentiality versus safety or legal mandate"}, {"id": "1c2164ff-ddc0-4af9-a3d2-164aaf434eca", "type": "concept", "title": "Agency policy, law, professional values, and client priorities"}], "description": "This subtopic introduces the recurring conflicts that make ethical practice demanding."}, {"id": "74b0fd59-7521-452b-b561-3ab61a5356c3", "type": "subtopic", "title": "Ethics as everyday practice", "children": [{"id": "db95b8fa-8a80-4ddd-b4fb-cebe4140ae4d", "type": "concept", "title": "Respectful communication and reliable commitments"}, {"id": "ec2048a0-35e5-4e1f-ab19-d804d1c35e61", "type": "concept", "title": "Small decisions with cumulative ethical impact"}, {"id": "f27a8ca9-0fe8-4e6b-b5fd-8e1cf8559289", "type": "concept", "title": "Habits of consultation, reflection, documentation, and repair"}], "description": "Students learn that ethics appears in ordinary decisions about language, documentation, time, power, referrals, and follow-through."}]}, {"id": "c89c06f7-bf2f-45e0-9e15-c51ae58af309", "type": "topic", "title": "NASW Code of Ethics, CSWE Competencies, and Professional Regulation", "description": "This topic grounds the course in formal professional standards, educational competencies, licensure expectations, and regulatory accountability.", "children": [{"id": "e1e214c2-70b3-44f5-8532-eb766dd595c4", "type": "subtopic", "title": "NASW Code structure", "children": [{"id": "a6029c33-c45f-44c4-8f44-9fadd6414eb3", "type": "concept", "title": "Preamble, purpose, ethical principles, and standards"}, {"id": "469bb451-0231-42bf-9dca-a74c8e806435", "type": "concept", "title": "Responsibilities to clients, colleagues, practice settings, profession, and society"}, {"id": "4b12beab-11e0-4a4a-b6db-5db2694b9768", "type": "concept", "title": "Using the Code in case analysis and documentation"}], "description": "Students learn how the Code organizes values, principles, and standards for professional conduct."}, {"id": "2bc5c8f4-a4f3-49ee-8007-3f7cc011a334", "type": "subtopic", "title": "Education, licensure, and regulation", "children": [{"id": "dab9a3c3-adb2-4aaf-9550-0be54de4679d", "type": "concept", "title": "CSWE competencies and field expectations"}, {"id": "b9f34b71-f067-434e-b608-94da2fa98f99", "type": "concept", "title": "State licensing boards, ASWB, supervision, and continuing education"}, {"id": "c029bbf1-9197-4b2d-ac04-f4b4e06990e6", "type": "concept", "title": "Complaints, discipline, sanctions, and due process"}], "description": "This subtopic explains how professional expectations appear in social work education, licensure, and public protection."}, {"id": "ef6f8e56-7701-4760-8807-b6b3bc603c8d", "type": "subtopic", "title": "Agency policy and legal context", "children": [{"id": "1fa5e7bf-ede8-4b94-ad54-ab8816210b75", "type": "concept", "title": "Agency procedures and ethical practice standards"}, {"id": "da109097-c9a1-4714-aafe-cc256ad0dbac", "type": "concept", "title": "Mandatory law, permissive law, and professional judgment"}, {"id": "4b3eabc9-5529-4d6f-9b03-8175f0c85de2", "type": "concept", "title": "When policies conflict with ethical responsibilities"}], "description": "Students learn to connect professional ethics to local policies, contracts, statutes, and regulations."}]}, {"id": "cc5399bc-a54b-4f00-bbac-84ff117fcf5c", "type": "topic", "title": "Ethical Decision-Making Models and Moral Reasoning", "description": "Students learn structured ways to analyze dilemmas, weigh competing duties, consult appropriately, document reasoning, and act with integrity.", "children": [{"id": "27c92837-b117-4f46-a879-8b3b1c0dde92", "type": "subtopic", "title": "Decision-making frameworks", "children": [{"id": "32c8b3a5-f3d1-4dd9-a907-b9d3385adfc7", "type": "concept", "title": "Identify facts, stakeholders, values, duties, and conflicts"}, {"id": "2244b1fd-9cb3-4728-81c2-1d538fbcb92c", "type": "concept", "title": "Generate options, consequences, consultation needs, and documentation steps"}, {"id": "8d8f53bd-6acc-4e1b-9992-a04f45a4d2a2", "type": "concept", "title": "Choose, act, evaluate, and revise when new facts emerge"}], "description": "Students practice structured models that slow down complex cases and make reasoning visible."}, {"id": "a45a55b8-949d-4987-91f3-076ef9b00728", "type": "subtopic", "title": "Moral reasoning and competing duties", "children": [{"id": "71dadea4-14f7-4fe6-8dbd-650a281fc628", "type": "concept", "title": "Autonomy, beneficence, nonmaleficence, justice, fidelity, and veracity"}, {"id": "e3c81a72-dc83-40a0-ae30-57ca1e806114", "type": "concept", "title": "Rights-based, care-based, virtue, consequentialist, and duty-based reasoning"}, {"id": "1ec4a31a-ecb2-4070-b034-b31dbce18e43", "type": "concept", "title": "Moral distress, ambiguity, and imperfect choices"}], "description": "This subtopic develops the ability to weigh principles when no option is perfect."}, {"id": "c19fd9aa-32e6-4853-bd1b-61383c58c0ea", "type": "subtopic", "title": "Consultation and defensible practice", "children": [{"id": "56e58e16-2fc0-4cf4-8355-8ee88870c57c", "type": "concept", "title": "Supervision, ethics consultation, legal consultation, and peer consultation"}, {"id": "936fea8e-2632-440a-a1f9-dd833a99cf9b", "type": "concept", "title": "Documenting questions, advice, rationale, and follow-up"}, {"id": "73c37a7e-3010-47fd-9e74-7b2fab50dc3c", "type": "concept", "title": "Avoiding isolated decision-making in high-risk cases"}], "description": "Students learn how consultation strengthens ethical judgment and accountability."}]}, {"id": "4cf0cd9d-b7bb-4cb1-81f4-22323bd1238a", "type": "topic", "title": "Self-Determination, Informed Consent, and Client Autonomy", "description": "This section explores how social workers respect autonomy while navigating vulnerability, capacity, coercion, safety, and institutional constraints.", "children": [{"id": "366098fc-e621-4b58-80f7-8f97ffaa504d", "type": "subtopic", "title": "Self-determination", "children": [{"id": "8fee9cac-5bd9-40e1-94c3-2c4a72a4b27c", "type": "concept", "title": "Client goals, preferences, refusal, and informed choice"}, {"id": "187349ea-e06e-4dc9-802b-85d60ed1521e", "type": "concept", "title": "Paternalism, coercion, compliance, and professional authority"}, {"id": "2af9d6ef-5e23-4ab7-8af1-fc33073b9bb5", "type": "concept", "title": "Harm reduction and least-restrictive alternatives"}], "description": "Students examine how to respect client choice while recognizing power imbalance, risk, and institutional constraints."}, {"id": "0efc6276-e4ec-4673-8f61-c6b22a899527", "type": "subtopic", "title": "Informed consent", "children": [{"id": "307c834f-ddd7-4a52-a395-9657add5e80a", "type": "concept", "title": "Purpose, risks, benefits, alternatives, limits, fees, records, and confidentiality"}, {"id": "4d4bf4cf-eae1-4bbe-a5ae-c1b0c93c02ed", "type": "concept", "title": "Plain language, interpretation, accessibility, and checking understanding"}, {"id": "9ec83fcc-f4c3-40a3-aa95-02e5caafc9bd", "type": "concept", "title": "Consent in agencies, schools, healthcare, courts, and digital practice"}], "description": "This subtopic teaches consent as an ongoing communication process rather than a signed form."}, {"id": "c1a51dfd-e1cd-4f42-b2c8-b2543a647b8b", "type": "subtopic", "title": "Capacity and substitute decision-making", "children": [{"id": "0868227b-84ab-40d3-96d3-4ab250756f80", "type": "concept", "title": "Decision-specific capacity and supported decision-making"}, {"id": "bc87f4d2-0f10-44f3-8663-b1e9634f641a", "type": "concept", "title": "Guardianship, advance directives, minors, and surrogate decision makers"}, {"id": "c1463569-64d6-4664-9c4a-63ec4047fa96", "type": "concept", "title": "Documentation, consultation, and rights protection"}], "description": "Students learn how capacity questions complicate autonomy and protection."}]}, {"id": "8e166591-b998-42b9-8d5d-3688af15a308", "type": "topic", "title": "Confidentiality, Privacy, Privilege, and Information Sharing", "description": "Students learn how to protect client information while understanding exceptions, collaboration demands, legal limits, and ethical communication.", "children": [{"id": "e7cd5315-20d9-4b60-a6be-628e722fe719", "type": "subtopic", "title": "Confidentiality foundations", "children": [{"id": "9ff52ef4-563c-4f06-95d8-cc0f622491e4", "type": "concept", "title": "Privacy, confidentiality, privilege, and records access"}, {"id": "c126d042-e553-4831-8696-57f9705a7024", "type": "concept", "title": "Limits of confidentiality and duty to explain them early"}, {"id": "d1a0455f-d4bf-4459-83bc-110d1df54ec4", "type": "concept", "title": "Minimum necessary disclosure and purpose-limited sharing"}], "description": "Students learn why confidentiality is central to trust and when it may be limited."}, {"id": "fa66ab93-1ad5-4d1c-a76a-b8831ea2e336", "type": "subtopic", "title": "Information sharing and exceptions", "children": [{"id": "09f5ed38-e448-400a-966b-88e767b25ebb", "type": "concept", "title": "Mandated reporting, imminent harm, court orders, releases, and subpoenas"}, {"id": "89ced11f-a317-4d03-98fa-daad846154c0", "type": "concept", "title": "Team-based care, schools, hospitals, child welfare, and integrated services"}, {"id": "a0e70f2e-caef-4650-bea0-1f3aa46376cc", "type": "concept", "title": "Client consent, revocation, and documentation of disclosures"}], "description": "This subtopic examines situations where disclosure may be required, permitted, or ethically justified."}, {"id": "a631d9cb-171d-47f9-9e50-0105f34c6872", "type": "subtopic", "title": "Privacy in practice environments", "children": [{"id": "1072e435-6b79-4dea-bea4-c59f16d592a6", "type": "concept", "title": "Phone calls, email, texts, waiting rooms, home visits, and shared offices"}, {"id": "3f4eae32-a3d4-4ca5-8ebb-6e40fd89d5ae", "type": "concept", "title": "Interpreter use, family requests, collateral contacts, and case conferences"}, {"id": "4a0fb0d9-92be-4cc0-b954-de3560625217", "type": "concept", "title": "Record access, correction requests, and secure storage"}], "description": "Students learn to protect information in everyday agency settings."}]}, {"id": "f5adf786-2a81-49f5-87dc-323bf0a70ff4", "type": "topic", "title": "Documentation, Records, Case Notes, and Risk Management", "description": "This topic treats documentation as ethical practice: records can protect dignity, continuity, accountability, and legal defensibility, or they can reproduce harm.", "children": [{"id": "b5e588b1-13a5-460c-869e-cc16f23a24e1", "type": "subtopic", "title": "Ethical documentation", "children": [{"id": "e0ca9e93-7b4f-4261-afc8-91eca358afa2", "type": "concept", "title": "Accuracy, relevance, timeliness, clarity, and respectful language"}, {"id": "e4a75e7b-dcad-4283-9fbf-beffd0e24eba", "type": "concept", "title": "Objective facts, professional judgment, quotes, and avoiding bias"}, {"id": "2488fc34-6b6d-418c-bf4e-fc93ad49c2f5", "type": "concept", "title": "Documenting consent, consultation, risk, referrals, and follow-up"}], "description": "Students learn how records should support care, continuity, dignity, and accountability."}, {"id": "b1483d87-f783-441b-86ab-834bee21f1b9", "type": "subtopic", "title": "Record rights and legal defensibility", "children": [{"id": "ea1d7c31-edbf-460f-902d-2d730db1291f", "type": "concept", "title": "Client access, amendments, subpoenas, audits, and retention"}, {"id": "6cbc4735-aef0-4014-8678-9cfa830e6be2", "type": "concept", "title": "Case notes, progress notes, incident reports, and supervision notes"}, {"id": "8dbfe660-6c53-4396-9c19-5d141b46e980", "type": "concept", "title": "Risk management through clear reasoning and transparent practice"}], "description": "This subtopic teaches students to write records that can withstand review without becoming defensive or dehumanizing."}, {"id": "04d9e0c8-7acd-41b7-9c7b-2a0a8a731df2", "type": "subtopic", "title": "Documentation harms", "children": [{"id": "bb1cc20a-7aa8-493d-8a81-003be02618cb", "type": "concept", "title": "Deficit language, unsupported conclusions, and coded bias"}, {"id": "63637189-6462-4eed-8352-2ee77929f901", "type": "concept", "title": "Sensitive information, third-party information, and future audience risks"}, {"id": "3e9a0941-dc56-4c6b-986b-e25a0bbeb43e", "type": "concept", "title": "Trauma-informed, strengths-based, and culturally responsive documentation"}], "description": "Students learn how records can stigmatize, criminalize, surveil, or misrepresent clients."}]}, {"id": "7db7e274-fead-4d7c-9e45-23f4867ff736", "type": "topic", "title": "Professional Boundaries, Dual Relationships, and Conflicts of Interest", "description": "Students learn to recognize, prevent, manage, and document boundary risks across direct practice, communities, small towns, schools, agencies, and digital spaces.", "children": [{"id": "06dc4cb4-3454-4bd4-a1d8-d10e84a7ad94", "type": "subtopic", "title": "Boundary principles", "children": [{"id": "7407b0f3-d477-444b-b489-da05204f0870", "type": "concept", "title": "Role clarity, time, place, communication, touch, gifts, and personal relationships"}, {"id": "2ba0a5bd-a1df-4f93-a30c-b3d0fcee4f9f", "type": "concept", "title": "Power imbalance and client vulnerability"}, {"id": "93d81ff3-bbce-49a3-99df-c907a8b432ed", "type": "concept", "title": "Boundary crossings versus boundary violations"}], "description": "Students learn to distinguish therapeutic/professional boundaries from rigidity or avoidance."}, {"id": "df1d8860-7c32-4eb1-a75b-03aab4cfa6af", "type": "subtopic", "title": "Dual and multiple relationships", "children": [{"id": "267f5600-7a5f-4daf-9934-6a101e963938", "type": "concept", "title": "Small towns, faith communities, schools, tribal communities, online spaces, and prior relationships"}, {"id": "c6d9193c-2c76-4782-8d6e-4c69ba83f13a", "type": "concept", "title": "Avoidance, management, informed consent, consultation, and documentation"}, {"id": "8333a00c-9673-49a8-80b6-e810c830ebfa", "type": "concept", "title": "Power, exploitation, favoritism, and service access"}], "description": "This subtopic explores situations where professional and personal/community roles overlap."}, {"id": "04bf2518-6dba-4e07-8d39-0b109b74c258", "type": "subtopic", "title": "Conflicts of interest", "children": [{"id": "cc83bac6-31b5-4307-ba18-1487685d1ede", "type": "concept", "title": "Personal gain, agency pressure, funder pressure, family requests, and referral relationships"}, {"id": "ed30d5cc-623a-46a9-9e14-6947f09e04b3", "type": "concept", "title": "Transparency, recusal, supervision, and disclosure"}, {"id": "8e8f0fd5-03f0-4f4a-98e4-b15128b86eb0", "type": "concept", "title": "Conflicts in administration, advocacy, and community work"}], "description": "Students learn to identify competing loyalties that may distort judgment."}]}, {"id": "f9b57e22-5728-4d9a-8a35-3eefdd1dffda", "type": "topic", "title": "Self-Disclosure, Professional Use of Self, and Reflective Practice", "description": "This section helps students use their identity, values, emotions, and experience intentionally rather than impulsively or defensively.", "children": [{"id": "046c6725-7c72-42d0-a99a-360cd680931b", "type": "subtopic", "title": "Self-disclosure", "children": [{"id": "bcb69076-10e6-468f-87da-a3738fc9d6b2", "type": "concept", "title": "Purpose, timing, amount, relevance, and client impact"}, {"id": "fca7b72a-e4ec-4794-af89-744f7038f40f", "type": "concept", "title": "Disclosures about identity, lived experience, values, grief, recovery, and opinion"}, {"id": "24bbca80-f7c2-4bc5-b067-4c981cf2bf0d", "type": "concept", "title": "Documentation and supervision around disclosure choices"}], "description": "Students learn to evaluate when disclosure serves the client and when it serves the worker."}, {"id": "5335bcf3-fea9-4813-baf7-00094252afba", "type": "subtopic", "title": "Professional use of self", "children": [{"id": "f1f28896-7980-4958-97d3-fce771910099", "type": "concept", "title": "Authenticity, boundaries, humility, and role clarity"}, {"id": "16db387f-aa6f-4653-8bc3-948211918085", "type": "concept", "title": "Countertransference-like reactions, triggers, and values conflicts"}, {"id": "ad8507e0-b72a-4f28-b62d-8dc2f556c996", "type": "concept", "title": "Repair after mistakes and feedback-informed practice"}], "description": "This subtopic helps students use presence, identity, emotion, and authority ethically."}, {"id": "40b2038e-3001-4403-9851-ea57774f308f", "type": "subtopic", "title": "Reflective practice", "children": [{"id": "84640038-1a51-490c-965d-ed6061c9c500", "type": "concept", "title": "Reflective journaling, supervision questions, and peer consultation"}, {"id": "266522d8-8c28-45f0-99b5-5a502b3c503c", "type": "concept", "title": "Ethical humility, uncertainty, and learning from discomfort"}, {"id": "44e4100c-d0c9-4e4b-ae4e-a2e9be992bb2", "type": "concept", "title": "Professional formation plans and accountability commitments"}], "description": "Students learn habits that sustain ethical growth over a career."}]}, {"id": "8d526e82-c183-442b-a3e1-f0c36043038e", "type": "topic", "title": "Competence, Scope of Practice, Supervision, Impairment, and Self-Care", "description": "Students examine competence as an ethical obligation involving training, supervision, consultation, impairment, wellness, and responsible referral.", "children": [{"id": "0b813989-858f-437c-9ddc-3c3167050e72", "type": "subtopic", "title": "Professional competence", "children": [{"id": "eadbe68e-c068-4112-91c4-0676a5bb95a3", "type": "concept", "title": "Education, training, licensure, consultation, and continuing competence"}, {"id": "e5901f24-4393-4dec-9e91-9537a70b3147", "type": "concept", "title": "Scope of practice, referral, and responsible service limits"}, {"id": "728ff1f7-f739-49a6-91d5-a0ed5a76e37f", "type": "concept", "title": "Competence with populations, methods, technology, and cultural contexts"}], "description": "Students examine competence as a living obligation rather than a credential once earned."}, {"id": "ac042f97-e29f-442c-8afd-612b3f724dc0", "type": "subtopic", "title": "Supervision and consultation", "children": [{"id": "75ede04f-d7e6-4953-b030-597a89b89866", "type": "concept", "title": "Learning contracts, supervision agendas, and feedback"}, {"id": "3e5876f5-038c-4c16-9eb9-978fd5e7f5a0", "type": "concept", "title": "Using supervision for risk, bias, uncertainty, boundaries, and mistakes"}, {"id": "debf73ba-f5e9-4105-bdb8-58803bc912a0", "type": "concept", "title": "Documentation of supervision and consultation"}], "description": "This subtopic connects ethical practice to learning, oversight, and shared accountability."}, {"id": "744fd9c4-967f-4dcc-af99-81e4220d7d46", "type": "subtopic", "title": "Impairment and self-care", "children": [{"id": "7affe5ec-0169-49cf-ae64-b3aeba8981f2", "type": "concept", "title": "Recognizing impairment and diminished judgment"}, {"id": "f644d105-0795-499d-9450-3d1af2139125", "type": "concept", "title": "Duty to seek help, modify workload, or step back"}, {"id": "c0457658-4863-4a94-9aa4-c4df18d6d680", "type": "concept", "title": "Self-care, organizational responsibility, and workforce sustainability"}], "description": "Students learn how personal distress, burnout, illness, substance use, or trauma exposure can create ethical risk."}]}, {"id": "391886bd-9fc3-4705-8840-c39a258a17cf", "type": "topic", "title": "Cultural Humility, Anti-Oppressive Practice, and Justice Ethics", "description": "This topic places ethics inside power, oppression, identity, cultural humility, human rights, and social justice obligations.", "children": [{"id": "18255b36-0380-4187-8e82-dcb99dc1d118", "type": "subtopic", "title": "Cultural humility", "children": [{"id": "24629e60-7f42-4a8c-b8b1-638a0476c080", "type": "concept", "title": "Humility versus competence"}, {"id": "6972ec53-19ab-4c8d-9229-93dff7e257aa", "type": "concept", "title": "Client-defined meaning, language access, and accessibility"}, {"id": "c363c6b9-6d5d-4a0a-9a1e-a3a9e007cf20", "type": "concept", "title": "Avoiding stereotypes, tokenism, and cultural essentialism"}], "description": "Students learn that ethical practice requires lifelong learning, power analysis, and accountability across difference."}, {"id": "24e93b35-f44d-4e6c-a63a-bcd275c7b728", "type": "subtopic", "title": "Anti-oppressive ethics", "children": [{"id": "08ed78fb-4edf-4266-b111-c515718bf1ce", "type": "concept", "title": "Racism, sexism, ableism, classism, heterosexism, transphobia, xenophobia, religious oppression, and colonialism"}, {"id": "c4c5863e-a577-4c20-bed5-a1371df1f7d2", "type": "concept", "title": "Institutional harm, surveillance, coercion, and deficit framing"}, {"id": "e9b4ece9-98d8-4468-8c99-b3df02bd26e2", "type": "concept", "title": "Equity, dignity, rights, and community accountability"}], "description": "This subtopic places ethical decisions inside structural power and injustice."}, {"id": "8d7e684a-75c8-42dc-9ad7-c3b92ed10a58", "type": "subtopic", "title": "Justice and advocacy duties", "children": [{"id": "b064fa8b-ca99-46e9-946b-74e8141da674", "type": "concept", "title": "Social justice obligations in the NASW Code"}, {"id": "e7b86ddb-f0f6-4e77-bf91-e2178f538d5b", "type": "concept", "title": "Policy advocacy, resource access, and challenging unjust practices"}, {"id": "ce556479-56e6-4ba3-b12c-dd1565d99a17", "type": "concept", "title": "Solidarity, allyship, and accountable use of professional power"}], "description": "Students examine the ethical relationship between individual service and systems change."}]}, {"id": "5e58bd4f-4074-46b5-98df-40ee594b2ac9", "type": "topic", "title": "Mandated Reporting, Safety, Duty to Protect, and Coercive Systems", "description": "Students analyze high-stakes situations where safety, confidentiality, client trust, legal mandates, and institutional power collide.", "children": [{"id": "b2b1c57e-d7e1-448d-acec-9e3e5eb155d6", "type": "subtopic", "title": "Mandated reporting", "children": [{"id": "537035ea-adc6-4153-9107-aecaac95c725", "type": "concept", "title": "Child abuse, elder abuse, vulnerable adult abuse, and jurisdictional variation"}, {"id": "815d90bc-54a3-4fc9-b4db-cd98c490f467", "type": "concept", "title": "Explaining mandates during informed consent"}, {"id": "f3d81834-bebf-4159-822d-3613a730d4ad", "type": "concept", "title": "Client trust, safety planning, documentation, and consultation"}], "description": "Students learn the ethics and limits of legal reporting duties."}, {"id": "898f4d4d-1337-49e8-8714-bcf15448eada", "type": "subtopic", "title": "Threats, suicide risk, and duty to protect", "children": [{"id": "48593d6b-d9da-417b-b066-371c695345be", "type": "concept", "title": "Risk assessment, protective action, emergency intervention, and least-restrictive alternatives"}, {"id": "aa46afa3-fffc-4b0f-ad47-330d1d142ca1", "type": "concept", "title": "Duty to warn/protect concepts and legal variation"}, {"id": "982c96b4-2f0e-4fd4-810b-5031ef06dc74", "type": "concept", "title": "Consultation, documentation, and follow-up after crisis decisions"}], "description": "This subtopic explores high-stakes risk decisions involving possible harm."}, {"id": "c9f76366-d7bb-436d-a248-72c5ca76652f", "type": "subtopic", "title": "Coercive systems and ethical tension", "children": [{"id": "76648856-034a-414e-9c76-1792a9d3e5a1", "type": "concept", "title": "Child welfare, courts, schools, hospitals, shelters, immigration, and corrections"}, {"id": "ffaed680-dbde-4037-9792-07b22f2de1da", "type": "concept", "title": "Voluntary versus involuntary services"}, {"id": "6f41844c-20cd-447d-bf18-de0abe580770", "type": "concept", "title": "Minimizing harm, transparency, rights, and advocacy within constraints"}], "description": "Students examine ethical practice when social workers operate in systems with surveillance or control powers."}]}, {"id": "ffcdafbb-afc9-4b85-9eb5-669092d4f24f", "type": "topic", "title": "Ethics with Individuals, Families, Groups, Communities, and Organizations", "description": "This section shows how ethical issues change across micro, mezzo, and macro practice settings.", "children": [{"id": "1cc452ff-f488-4181-be2a-292a2e095fdb", "type": "subtopic", "title": "Micro practice ethics", "children": [{"id": "e1afd1c1-7bd5-4b74-b92e-31f2b9b52b2d", "type": "concept", "title": "Engagement, assessment, contracting, intervention, termination, and referral"}, {"id": "4749afd7-4232-45aa-a048-7d974fdced10", "type": "concept", "title": "Family confidentiality, competing interests, minors, and collateral contacts"}, {"id": "5213b21f-0963-4a47-9fbb-a796f8ab35ec", "type": "concept", "title": "Power, dependency, boundaries, and informed consent"}], "description": "Students apply ethics to direct relationships with individuals and families."}, {"id": "f61a4310-be59-49dd-87e2-f7605c531acb", "type": "subtopic", "title": "Group and community practice ethics", "children": [{"id": "df57f1e9-1dc8-4b2f-90f7-687498a831fb", "type": "concept", "title": "Group confidentiality, group norms, consent, conflict, and facilitation"}, {"id": "b1bfcfd6-963c-4bae-a3b9-5537d6eac8b9", "type": "concept", "title": "Community representation, participation, and accountability"}, {"id": "b6fa74cb-3927-4780-afb4-e88194079931", "type": "concept", "title": "Power analysis, coalition ethics, and avoiding extraction"}], "description": "This subtopic expands ethical thinking beyond one-to-one practice."}, {"id": "994b3646-fde4-4700-a644-29b4cef06ae9", "type": "subtopic", "title": "Organizational ethics", "children": [{"id": "9ded6cf4-398a-4a60-be35-42479374b30a", "type": "concept", "title": "Workload, staffing, access, eligibility, waiting lists, and service termination"}, {"id": "5b028653-41c7-4963-a948-4a6f73c350b4", "type": "concept", "title": "Ethics audits, supervision systems, and grievance processes"}, {"id": "b0efae14-c1b9-4d22-bc1b-4bd26ba1edef", "type": "concept", "title": "Ethical climate, leadership, and organizational accountability"}], "description": "Students learn how agency decisions create ethical conditions for practice."}]}, {"id": "7ad1b0eb-77d6-4d79-a6c6-10dd8c4651c1", "type": "topic", "title": "Digital Practice, Telepractice, Social Media, AI, and Technology Ethics", "description": "Students address contemporary ethical risks in remote practice, digital records, social media, texting, platforms, algorithms, and AI-supported tools.", "children": [{"id": "6aec1192-a80a-4f6d-9d46-595be9d765c2", "type": "subtopic", "title": "Telepractice and digital communication", "children": [{"id": "16e2185e-e94e-4368-a906-6420b74af59c", "type": "concept", "title": "Telepractice consent, location, emergency planning, licensure, and jurisdiction"}, {"id": "df752585-4402-486f-86a6-58e5c77d12d6", "type": "concept", "title": "Texting, email, portals, video platforms, and response-time expectations"}, {"id": "3ae81944-f990-482c-ba22-11546ad12443", "type": "concept", "title": "Digital access, disability access, language access, and privacy"}], "description": "Students learn to adapt consent, confidentiality, boundaries, and competence to remote practice."}, {"id": "b9f75e70-e78b-4e23-9c77-846ffe5de2c4", "type": "subtopic", "title": "Social media and online boundaries", "children": [{"id": "9e88de6f-b017-484c-bfed-0943977320da", "type": "concept", "title": "Friending/following, searching clients, online reviews, and public posts"}, {"id": "9e534cc6-8c32-4c34-bd22-5ccc2bc22cc1", "type": "concept", "title": "Professional identity, privacy settings, and digital self-disclosure"}, {"id": "103b8928-6f41-4e76-b2da-287f7c23c26d", "type": "concept", "title": "Agency policies, documentation, and boundary consultation"}], "description": "This subtopic addresses the blurred lines created by online visibility and communication."}, {"id": "576b008a-fb4d-4378-b69d-bc68dd1c197d", "type": "subtopic", "title": "AI, data systems, and digital records", "children": [{"id": "ff4beeb9-e823-40a9-89d4-66ed10f2a84d", "type": "concept", "title": "Electronic health records, predictive tools, algorithms, and AI drafting"}, {"id": "2daba80a-a28e-422d-84fb-d71b763ef621", "type": "concept", "title": "Bias, transparency, consent, accuracy, surveillance, and accountability"}, {"id": "270d4c87-6ab7-4324-bccd-9a335b65265f", "type": "concept", "title": "Human review, documentation, and responsible technology adoption"}], "description": "Students consider emerging ethical issues in automated and data-driven systems."}]}, {"id": "addda05a-0e8d-4271-a3b8-d5fe8c907a73", "type": "topic", "title": "Research, Program Evaluation, Evidence, and Participant Protection", "description": "This topic connects social work ethics to IRB, informed consent in research, evaluation use, evidence claims, and responsible dissemination.", "children": [{"id": "acd8452d-9dab-4973-aff1-0e78f231f31f", "type": "subtopic", "title": "Research ethics and IRB", "children": [{"id": "403786ad-beeb-4212-94b3-1dc69c8e5c18", "type": "concept", "title": "Belmont principles, informed consent, privacy, risk, benefit, and justice"}, {"id": "ffd90b0d-f831-440f-af10-9f8289966482", "type": "concept", "title": "IRB review, vulnerable populations, incentives, and confidentiality"}, {"id": "e5a3aa65-b92a-4e32-b3d3-53a6c3f3cc29", "type": "concept", "title": "Community-based and participatory research ethics"}], "description": "Students learn the ethical foundations of research with human participants."}, {"id": "e17c4df3-af72-49b1-ac29-cc3cf1a63cb7", "type": "subtopic", "title": "Program evaluation ethics", "children": [{"id": "c9bf8504-229a-45aa-a9a9-1558b8eaa928", "type": "concept", "title": "Stakeholder engagement, consent, data ownership, and reporting obligations"}, {"id": "a11e24e9-3b18-42d0-9a00-a352f1f226eb", "type": "concept", "title": "Evaluation burden, power, and community-defined outcomes"}, {"id": "e4243637-a8e8-4ab5-b745-578c3d86e495", "type": "concept", "title": "Using findings responsibly and avoiding punitive misuse"}], "description": "This subtopic connects evaluation to accountability, improvement, and potential harm."}, {"id": "41405c59-579a-4540-8efd-0659fd2fd081", "type": "subtopic", "title": "Evidence-based practice ethics", "children": [{"id": "96e31ef6-a4d8-4c80-8215-24d52668556e", "type": "concept", "title": "Best available evidence, clinical expertise, and client values"}, {"id": "e0e80e3b-efec-4a01-afcc-ff98896a2cbd", "type": "concept", "title": "Limits, bias, generalizability, and implementation context"}, {"id": "7de997cd-a141-4d08-81f1-1a19e9e60cd3", "type": "concept", "title": "Transparency about uncertainty and shared decision-making"}], "description": "Students learn to use evidence without ignoring culture, context, values, or client preference."}]}, {"id": "b1d522fa-6ed7-4269-8e90-35902ab8bf2f", "type": "topic", "title": "Policy Practice, Advocacy, Administration, and Resource Allocation Ethics", "description": "Students examine ethical duties in policy advocacy, organizational leadership, budgeting, public communication, and scarce-resource decisions.", "children": [{"id": "70e595b4-84de-4a87-95b4-380cc3f25922", "type": "subtopic", "title": "Policy advocacy ethics", "children": [{"id": "3ec4b1ba-4837-4251-bd85-d82b50393ee3", "type": "concept", "title": "Truthfulness, representation, confidentiality, and client/community voice"}, {"id": "78b5cb5c-375a-46cc-8dab-5520d60d6e1b", "type": "concept", "title": "Lobbying rules, public testimony, media advocacy, and coalition accountability"}, {"id": "9af23a4d-3c27-4329-9c18-6e6c3ee0a647", "type": "concept", "title": "Balancing agency role, professional values, and political context"}], "description": "Students examine ethical responsibilities in public and systems-level practice."}, {"id": "0463ca14-e5ba-419e-aebd-6ad11724400a", "type": "subtopic", "title": "Administration ethics", "children": [{"id": "12765bd3-be34-45ca-ae41-34abf13a35ca", "type": "concept", "title": "Hiring, supervision, budgets, compliance, conflicts of interest, and data use"}, {"id": "cd1abb80-4c8b-4c55-b0dc-5daccde2507b", "type": "concept", "title": "Ethical climate, grievance systems, and board accountability"}, {"id": "45328d65-7782-4f7f-8ee4-389ae520addb", "type": "concept", "title": "Mission, funding pressure, and service quality"}], "description": "This subtopic shows how management decisions shape ethical practice conditions."}, {"id": "02c41e16-10c3-4be5-89c3-d4e1c5167956", "type": "subtopic", "title": "Resource allocation and rationing", "children": [{"id": "6de61cd0-06b3-4cef-b1bf-ec5e52b8ecfc", "type": "concept", "title": "Eligibility, waiting lists, triage, prioritization, and transparency"}, {"id": "5989a3ec-825c-4f60-b333-b86d7c37d7d6", "type": "concept", "title": "Equity, need, effectiveness, and community accountability"}, {"id": "27dd931f-7590-4e06-98a8-3ac62c2af1b5", "type": "concept", "title": "Documenting allocation criteria and appeal processes"}], "description": "Students learn to reason ethically when services, time, funds, or placements are scarce."}]}, {"id": "b8d98519-2d36-4606-a058-35483c0a95ac", "type": "topic", "title": "Interprofessional, Legal, Court, and Integrated Care Ethics", "description": "This section prepares students to work ethically across teams, courts, schools, hospitals, community agencies, and legal systems.", "children": [{"id": "13db9515-5db1-4f39-a736-624be03c2b9f", "type": "subtopic", "title": "Interprofessional collaboration", "children": [{"id": "2beb311f-25f6-4829-ba86-06fa377821f5", "type": "concept", "title": "Role clarity, scope, consultation, referrals, and communication"}, {"id": "eaf7e91d-8356-4137-b943-e1088135601e", "type": "concept", "title": "Team confidentiality, shared records, case conferences, and care coordination"}, {"id": "65057f8d-def0-42c7-b228-21dd0ccf5c36", "type": "concept", "title": "Managing disagreement and escalating concerns"}], "description": "Students learn to work ethically with teams whose disciplines have different duties and norms."}, {"id": "31d452fb-fe6d-4c20-b003-560c99633e0c", "type": "subtopic", "title": "Legal and court-related practice", "children": [{"id": "6a1eb134-8fb1-42c2-92ce-2db741794407", "type": "concept", "title": "Subpoenas, court orders, testimony, expert roles, and forensic boundaries"}, {"id": "73929c5f-930a-4698-bcc7-9562ca561880", "type": "concept", "title": "Client privilege, records release, and legal consultation"}, {"id": "1b95c774-6310-47f5-aacc-cf76dff8b3d8", "type": "concept", "title": "Neutrality, advocacy, truthfulness, and role conflicts"}], "description": "This subtopic examines social work ethics when legal systems shape practice."}, {"id": "3700c735-9571-47a0-bcf3-c87eeeb314d1", "type": "subtopic", "title": "Integrated care and institutional ethics", "children": [{"id": "5cf8b5fb-1e52-4644-9b68-d94118d6ba2a", "type": "concept", "title": "Consent, privacy, diagnosis, discharge, transitions, and continuity of care"}, {"id": "a57df037-f0c5-4db1-b991-4d1a561ed505", "type": "concept", "title": "Institutional pressure, billing, documentation, and risk systems"}, {"id": "653839ea-c1e1-482f-9459-6d284e803fac", "type": "concept", "title": "Client-centered advocacy inside complex systems"}], "description": "Students analyze ethical challenges in hospitals, schools, behavioral health, and community agencies."}]}, {"id": "52cfd829-9c98-4f5a-9ea6-2a696608768a", "type": "topic", "title": "Specialized Ethical Dilemmas Across Populations and Settings", "description": "Students apply ethical reasoning to child welfare, behavioral health, aging, disability, immigration, schools, housing, healthcare, and crisis settings.", "children": [{"id": "3350bc49-5718-4389-88ed-591c87661bfe", "type": "subtopic", "title": "Children, youth, and families", "children": [{"id": "e87b47b0-46d3-46f3-8fda-ad59fd454350", "type": "concept", "title": "Consent and assent, parental rights, confidentiality, and school records"}, {"id": "29eab498-cd99-4d9a-9a66-a296d0efe2ef", "type": "concept", "title": "Child welfare, foster care, reunification, and family preservation"}, {"id": "6cde9d6e-7634-453c-a09f-7f2870305849", "type": "concept", "title": "Adolescent autonomy, safety, and mandated reporting"}], "description": "Students apply ethics to settings where minors, caregivers, schools, courts, and safety systems intersect."}, {"id": "701898d7-234d-4494-9e26-669f6c949f0a", "type": "subtopic", "title": "Health, mental health, aging, and disability", "children": [{"id": "e0488402-9d31-446c-a14d-764d09725e9a", "type": "concept", "title": "Diagnosis, involuntary treatment, suicide risk, disability rights, and supported decision-making"}, {"id": "80470008-ac6e-4532-b68f-b32bb28c6c08", "type": "concept", "title": "Aging, guardianship, end-of-life, and caregiver conflict"}, {"id": "1f15d9d2-41b4-4cdc-82d9-bd932f02c3d3", "type": "concept", "title": "Health inequity, access, and integrated care"}], "description": "This subtopic addresses ethical issues involving capacity, care systems, stigma, and access."}, {"id": "dc9d4df3-d36a-44be-a21f-9ad54915c1b7", "type": "subtopic", "title": "Immigration, housing, crisis, and community settings", "children": [{"id": "94ec5634-b0d0-4385-a496-8748f4e3cc8e", "type": "concept", "title": "Immigration status, documentation fear, language access, and confidentiality"}, {"id": "757c40ec-ca1c-4844-989b-b95dfb2ff73e", "type": "concept", "title": "Homelessness, shelters, outreach, and resource scarcity"}, {"id": "669698e3-f774-4f84-9406-974b5f2c6d1e", "type": "concept", "title": "Crisis response, disaster work, community violence, and public systems"}], "description": "Students examine ethics in high-need settings shaped by policy, scarcity, and vulnerability."}]}, {"id": "c843fb18-6fc9-4ef7-82f6-d214230b6128", "type": "topic", "title": "Capstone Ethics Consultation and Professional Formation Portfolio", "description": "The course culminates in a portfolio where students demonstrate ethical reasoning, consultation, documentation, reflection, and professional growth.", "children": [{"id": "b0b49de7-33c8-494e-91d9-f9b842b8203e", "type": "subtopic", "title": "Complex dilemma selection", "children": [{"id": "31eec085-9961-4a82-9068-4d99723a6cb4", "type": "concept", "title": "Facts, unknowns, stakeholders, setting, law, policy, and professional standards"}, {"id": "5422cc61-2cb9-4085-bcb7-1ea5a3d1880d", "type": "concept", "title": "Values conflicts, power dynamics, cultural context, and risks"}, {"id": "3ce73057-4355-44f7-b510-59fbe8270fbf", "type": "concept", "title": "Consultation needs and decision points"}], "description": "Students choose or receive a complex ethics case that requires layered analysis."}, {"id": "f0b6579c-b38b-4a16-be21-d3e506b0d44f", "type": "subtopic", "title": "Ethics consultation portfolio", "children": [{"id": "7f42c6a8-0415-4a1c-98be-c24afada7e6f", "type": "concept", "title": "Decision model memo, consultation record, documentation sample, and action plan"}, {"id": "1451eba4-6ede-4cac-ab16-91ae7587d851", "type": "concept", "title": "Client rights, safety, justice, and risk management"}, {"id": "c15af164-b328-482a-860b-6afd516a18d5", "type": "concept", "title": "Alternative options, rationale, limits, and follow-up"}], "description": "This subtopic asks students to demonstrate professional-quality ethical reasoning and documentation."}, {"id": "2e0e76e5-edfe-48b8-b57c-e71fd9ca30dc", "type": "subtopic", "title": "Professional formation plan", "children": [{"id": "7f130602-2842-4ca0-9ca9-a6bcf2e847b1", "type": "concept", "title": "Strengths, growth edges, supervision needs, and continuing education"}, {"id": "fb7353ac-22ae-49e4-b364-7a4f6e131cd4", "type": "concept", "title": "Boundary plan, consultation habits, and self-care commitments"}, {"id": "1ca99e7c-b25c-42ff-841c-c35e9a9d4c89", "type": "concept", "title": "Accountability to clients, communities, colleagues, and the profession"}], "description": "Students close the course by identifying how they will continue growing as ethical practitioners."}]}], "dbBacked": true}$swetjson$::jsonb,
